#!/usr/bin/env bash
set -euo pipefail

# Compare two markdown benchmark reports generated by sh/benchmark_local_device.sh.
# Usage:
#   sh/compare_benchmark_reports.sh <baseline.md> <candidate.md>

if [[ $# -ne 2 ]]; then
  echo "Usage: sh/compare_benchmark_reports.sh <baseline.md> <candidate.md>" >&2
  exit 1
fi

BASE="$1"
CAND="$2"

if [[ ! -f "$BASE" || ! -f "$CAND" ]]; then
  echo "Both input files must exist." >&2
  exit 1
fi

extract() {
  local file="$1"
  awk -F'|' '
    /^\| [a-zA-Z0-9_]+/ {
      gsub(/^ +| +$/, "", $2);  # stage
      gsub(/^ +| +$/, "", $4);  # wall time "875s (14m 35s)"
      split($4, t, "s");
      sec=t[1]+0;
      print $2 "|" sec;
    }
  ' "$file"
}

TMP_BASE=$(mktemp)
TMP_CAND=$(mktemp)
extract "$BASE" > "$TMP_BASE"
extract "$CAND" > "$TMP_CAND"

echo "Comparing:"
echo "- baseline: $BASE"
echo "- candidate: $CAND"
echo
printf '| Stage | Baseline (s) | Candidate (s) | Delta (s) | Delta %% |\n'
printf '|---|---:|---:|---:|---:|\n'

while IFS='|' read -r stage base_sec; do
  cand_sec=$(awk -F'|' -v s="$stage" '$1==s {print $2}' "$TMP_CAND")
  if [[ -z "$cand_sec" ]]; then
    continue
  fi
  delta=$((cand_sec - base_sec))
  pct=$(awk -v b="$base_sec" -v d="$delta" 'BEGIN { if (b==0) print "0.0"; else printf "%.1f", (d*100.0)/b }')
  printf '| %s | %s | %s | %s | %s%% |\n' "$stage" "$base_sec" "$cand_sec" "$delta" "$pct"
done < "$TMP_BASE"

rm -f "$TMP_BASE" "$TMP_CAND"